import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography, Divider, Box } from '@mui/material';
// import { toast } from 'react-toastify';
import InputLabel from '@mui/material/InputLabel';
import { useFieldArray, useForm, Controller } from 'react-hook-form';
import GenerateToastConfig from 'src/components/toast-config/GenerateToastConfig';
import InputGallery from 'src/components/inputGallery';
import styles from './formManagement.module.scss'
import { axios } from '../../utils/axios';
import { useMyContext } from '../provider';
import InputField from '../../components/input/inputField';
import useResponsive from '../../hooks/useResponsive';
import TinyCmeEditor from "../../components/TinyCme/tinyEditor";

const ITEM_HEIGHT = 48;
const ITEM_PADDING_TOP = 8;
const MenuProps = {
  PaperProps: {
    style: {
      maxHeight: ITEM_HEIGHT * 4.5 + ITEM_PADDING_TOP,
      width: 250,
    },
  },
};
const fieldArrayName = 'works';
export default function FormManagementPage() {
  const navigate = useNavigate();  
  const [images, setImg] = useState("")
  const { i18 } = useMyContext()
  const isMobile = useResponsive("down", "sm")
  const [pages, setPages] = useState([]);

  const { control, reset, handleSubmit, getValues, setValue } = useForm();
  const { fields, replace, prepend, remove, move, insert } = useFieldArray({
    control, // control props comes from useForm (optional: if you are using FormProvider)
    name: fieldArrayName, // unique name for your Field Array
  });

  const fetchData = async () => {
   const res = await axios.get('module/admin/howItWorks')
   if(res.data.statusCode) {
    const data = res?.data?.data;
    if(Array.isArray(data?.works)) {
        reset({
            [fieldArrayName]: data?.works
        })
    }
   }
  }

  useEffect(()=>{
    fetchData();
  },[])

  const handleAdd = (index) => {
    insert(index, {
      "title": "",
      "description": "",
      "icon": ""
    });
  }

  const onSubmit = async (values) => {
    const mappedValues = {};
    mappedValues[fieldArrayName] = values[fieldArrayName].map((item)=>({
      title: item.title,
      description: item.description,
      icon: item.icon
    }))
    const res = await axios.put('module/admin/howItWorks', mappedValues);
    GenerateToastConfig(res.data.message, 'success');
  }

  const onSelectedImg = (img, data) => {
    if(img[0]) {
      const fields = getValues(fieldArrayName);
      const clonedFields = [...fields];
      clonedFields[data.index].icon = img[0].imagePath;
      replace(clonedFields);
    }
  }

  return (
    <>
      <Helmet>
        <title>{i18?.SIDEBAR?.HOW_DOES_IT_WORK || "How does it work"}</title>
      </Helmet>
      <Typography variant="h4" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                {i18?.SIDEBAR?.HOW_DOES_IT_WORK || "How does it work"}
              </Typography>
              <form onSubmit={handleSubmit(onSubmit)}>
              <div className='d-flex h-100 overflow-auto gap-2 align-items-start'>
              <div className='d-flex flex-column gap-3 w-100'>
              {fields.map((field, index)=>{
                return (<Card key={field.id} >
                    <Grid container sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                      <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
                        <Box sx={{ display: "flex", alignItems: "center" }}>
                          <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                            {i18?.FORM?.STEP || 'Step'} {index+1}
                          </Typography>
                        </Box>
                        <Box sx={{ display: "flex", alignItems: "center", gap: '10px' }}>
                        <Button sx={{
                          padding: "10px 58px 10px 58px"
                        }}
                        onClick={()=>handleAdd(index)}
                          variant="contained" disabled={false} >
                          {i18?.FORM?.ADD || "Add"}
                        </Button>
                        <Button sx={{
                          padding: "10px 58px 10px 58px"
                        }}
                        onClick={()=>remove(index)}
                          variant="contained" disabled={false} >
                          {i18?.FORM?.REMOVE || "Remove"}
                        </Button>
                        </Box>
                      </Grid>
                    </Grid>
                    <Divider sx={{ backgroundColor: "#333", margin: "10px 0px 10px 0px" }} />
                    <Grid container={!isMobile} sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                      <Grid container={!isMobile} sx={{ marginTop: '10px' }}>
                        <Grid item xs={12} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px'}}>
                            <Controller
                            control={control}
                            name={`${fieldArrayName}.${index}.title`}
                            render={({ field }) =>(<InputField
                                label={i18?.FORM?.TITLE || "Title"}
                                {...field}
                                sx={{
                                  margin: '10px 0px',
                                  width: '100%',
                                  '& .MuiInputBase-input.MuiOutlinedInput-input': {
                                    padding: '10.5px 14px'
                                  },
                                }}
                                type="firstname"
                                // error={firstname}
                                // helperText={firstname}
                              />)} 
                            />
                          
                        </Grid>
                        
                      </Grid>
                      <Grid item xs={12} sx={{ padding: !isMobile ? '10px 50px  10px 0px' : '0px 5px' }}>
                      <InputLabel sx={{ color: "#2B3343" }} id="demo-simple-select-label">{i18?.FORM?.SUB_TITLE || "Sub Title"}</InputLabel>
                      <Controller
                            control={control}
                            name={`${fieldArrayName}.${index}.description`}
                            render={({field})=>(
                              <TinyCmeEditor {...field} />
                            )}
                            />
                             {/* // render={({ field }) =>(<textarea
                            //     rows={5}
                            //     {...field}
                            //     className="textArea"
                            //     placeholder="Enter text here..."
                            //     style={{
                            //       width: '100%',
                            //       marginBottom: '20px',
                            //       padding: '8px',
                            //       borderRadius: '4px',
                            //       borderColor: '#ccc',
                            //       resize: 'none',
                            //     }} */}
                      </Grid>

                      <div className='d-flex gap-2 w-100 mb-3'>
                      <InputGallery
              category='icons'
              fnc={onSelectedImg}
              fncData={{index}}
              selectedImages={field.icon?[field.icon]:[]}
              imageCount={1}
              />
                    </div>
                    </Grid>
                  </Card>)
              })}
              <Grid container justifyContent="flex-end" gap={2} sx={{ padding: '10px 30px', margin: '10px 0px' }}>
                        <Button sx={{
                          padding: "10px 58px 10px 58px"
                        }}
                        onClick={()=>reset()}
                          variant="contained" disabled={false} >
                          {i18?.FORM?.Reset || "Reset"}
                        </Button>

                        <Button sx={{
                          padding: "10px 58px 10px 58px"
                        }}
                        onClick={()=>handleAdd(fields.length)}
                          variant="contained" disabled={false} >
                          {i18?.FORM?.ADD || "Add"}
                        </Button>

                        <Button sx={{
                          padding: "10px 58px 10px 58px"
                        }}
                        type="submit"
                          variant="contained" disabled={false} >
                          {i18?.FORM?.SAVE || "Save"}
                        </Button>
                      </Grid>
              </div>
              </div>
              </form>
    </>
  );
}
